text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي",
  "planted": [
    {
      "slot": "p1",
      "text": "تعتمد الشركة على المصلحة المشروعة لمعالجة بيانات المستخدمين، ويستثنى من ذلك البيانات المتعلقة بالأصل العرقي، أو المعتقدات الدينية والسياسية، والسجلات الجنائية، والبيانات الحيوية والجينية والصحية، حيث يحظر استخدامها لهذا الغرض أو لأغراض التسويق، مع قصر الاطلاع على البيانات الصحية للموظفين المصرح لهم حصراً."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية للرسوم المقررة المعلن عنها في موقعنا الإلكتروني، والتي تعد غير قابلة للاسترداد بعد اتمام عملية الدفع.",
    "تتم عمليات السداد عبر وسائل الدفع الإلكترونية المعتمدة والمتاحة على المنصة وقت إتمام المعاملة.",
    "يبدأ سريان هذا العقد فور قبول الشروط، ويحق لأي طرف إنهاء التعاون بموجب إشعار كتابي يسبق موعد الإنهاء بثلاثين يوماً.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الناتجة عن سوء استخدام الخدمات المقدمة.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية."
  ]
}
